inline bool loginAccount(HWND owner,const fs::path& root,json& settings){if(!accountSession)accountSession=std::make_shared<AccountSession>(root);AccountDialog dialog;dialog.base=str(settings,"api");static bool registered=false;if(!registered){WNDCLASSW klass{};klass.hInstance=GetModuleHandle(nullptr);klass.lpszClassName=L"SnuwAccountLogin";klass.lpfnWndProc=AccountDialog::proc;klass.hCursor=LoadCursor(nullptr,IDC_ARROW);klass.hbrBackground=(HBRUSH)(COLOR_WINDOW+1);if(!RegisterClassW(&klass))throw std::runtime_error("로그인 창 준비 실패");registered=true;}HWND window=CreateWindowExW(WS_EX_DLGMODALFRAME,L"SnuwAccountLogin",L"snuwcanvas · 로그인",WS_CAPTION|WS_SYSMENU, CW_USEDEFAULT,CW_USEDEFAULT,558,464,owner,nullptr,GetModuleHandle(nullptr),&dialog);if(!window)throw std::runtime_error("로그인 창 생성 실패");if(owner)EnableWindow(owner,FALSE);ShowWindow(window,SW_SHOW);MSG message;while(!dialog.done&&GetMessageW(&message,nullptr,0,0)>0){if(!IsDialogMessageW(window,&message)){TranslateMessage(&message);DispatchMessageW(&message);}}if(owner){EnableWindow(owner,TRUE);SetForegroundWindow(owner);}if(dialog.ok){settings["api"]=dialog.base;settings["api_key"]=accountCredential;settings["content_mode"]="standard";}return dialog.ok;}
